#!/usr/bin/env node
// =====================================================================
//  Penghubung AI - PRD Generator
//  Menjalankan agy / Claude CLI / Codex di KOMPUTER INI (memakai login
//  OAuth milikmu) untuk web PRD Generator.
//
//  Dua cara kerja (dipilih otomatis dari file yang kamu download):
//  - Web di server (cPanel): program ini mengambil tugas dari server.
//  - Web statis (GitHub Pages): program ini membuka pintu kecil HANYA di
//    komputer ini (http://127.0.0.1:47615) dan hanya menerima permintaan
//    dari alamat web tempat kamu mendownloadnya + kode rahasiamu.
//
//  - Login/token CLI tidak pernah dikirim ke server. Program ini hanya
//    mengambil tugas (prompt) dari web, menjalankan CLI, lalu mengirim
//    hasil teksnya kembali.
//  - CLI dijalankan di folder sementara yang kosong, lalu folder dihapus.
//  - Biarkan jendela ini terbuka selama memakai web. Tutup = berhenti.
//  - Butuh Node.js 18 atau lebih baru (https://nodejs.org).
// =====================================================================
import { spawn, spawnSync } from "node:child_process";
import { timingSafeEqual } from "node:crypto";
import { createServer } from "node:http";
import { mkdtemp, readFile, rm, stat, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

// Diisi otomatis oleh web saat kamu klik "Download penghubung". Kode ini RAHASIA: jangan dibagikan.
const SERVER = (process.env.PRD_SERVER || "__SERVER__").replace(/\/$/, "");
const CODE = process.env.PRD_BRIDGE_CODE || "__CODE__";
// "direct:https://alamat-web" = mode langsung untuk web statis (tanpa server).
const DIRECT = SERVER.startsWith("direct:") ? SERVER.slice(7) : "";
const PORT = 47615; // web statis memanggil alamat ini; jangan diubah

const VERSION = 5;
const isWin = process.platform === "win32";
const env = (k) => process.env[k]?.trim() || "";
const BIN = { agy: env("AGY_BIN") || "agy", "claude-cli": env("CLAUDE_BIN") || "claude", codex: env("CODEX_BIN") || "codex" };
const LABEL = { agy: "agy (Antigravity)", "claude-cli": "Claude CLI", codex: "Codex CLI" };
const AGY_AUTO = env("AGY_AUTO_APPROVE") !== "0";
const TIMEOUT_MS = Number(env("AI_TIMEOUT_MS")) || 8 * 60_000;
const MAX_JOBS = Math.max(1, Number(env("BRIDGE_MAX_JOBS")) || 3);
const MODEL_RE = /^[A-Za-z0-9][A-Za-z0-9._:/@-]{0,79}$/;
const EFFORT_RE = /^(minimal|low|medium|high|xhigh|max)$/;
const OUTPUT_FILES = ["hasil.json", "hasil.md", "hasil.html"];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const now = () => new Date().toLocaleTimeString();
const log = (...a) => console.log(`[${now()}]`, ...a);

function hasBin(bin) {
  try {
    return spawnSync(isWin ? "where" : "which", [bin], { stdio: "ignore" }).status === 0;
  } catch {
    return false;
  }
}

// ---------- Cek hasil sudah lengkap ----------
function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = fenced ? fenced[1] : text;
  const s = body.indexOf("{");
  const e = body.lastIndexOf("}");
  if (s < 0 || e <= s) throw new Error("no json");
  return JSON.parse(body.slice(s, e + 1));
}
const COMPLETE = {
  json: (s) => {
    try {
      extractJson(s);
      return true;
    } catch {
      return false;
    }
  },
  markdown: (s) => s.trim().length > 200 && /^#\s/m.test(s),
  html: (s) => /<\/html>/i.test(s),
};

// ---------- Menjalankan CLI (sama seperti aplikasi versi lokal) ----------
const quote = (a) => (isWin && /[\s"]/.test(a) ? `"${a.replace(/"/g, '\\"')}"` : a);
function killTree(child) {
  if (child.exitCode !== null || !child.pid) return;
  if (isWin) spawn("taskkill", ["/pid", String(child.pid), "/T", "/F"], { stdio: "ignore" });
  else child.kill("SIGTERM");
}

function buildRun(job, imageFiles) {
  const model = job.model && MODEL_RE.test(job.model) ? job.model : "";
  const effort = job.effort && EFFORT_RE.test(job.effort) ? job.effort : "";
  if (job.engine === "agy") {
    const task = `Baca file instruksi.md di folder ini lalu kerjakan persis seperti yang diminta. Tulis hasil akhirnya ke file ${job.outputFile} di folder ini.`;
    const note = imageFiles.length ? `\n\nGambar referensi dari user ada di folder ini: ${imageFiles.join(", ")}. Lihat gambar-gambar itu sebelum menjawab.` : "";
    return {
      bin: BIN.agy,
      args: ["-p", task, ...(model ? ["--model", model] : []), ...(effort ? ["--effort", effort] : []), ...(AGY_AUTO ? ["--dangerously-skip-permissions"] : [])],
      files: {
        "instruksi.md": `${job.instructions}${note}\n\n---\nPENTING: Tulis hasil akhir LENGKAP ke file "${job.outputFile}" di folder ini memakai tool tulis/edit file bawaan. JANGAN menjalankan perintah terminal/shell, jangan memasang apa pun, dan jangan membuat atau mengubah file lain. Setelah file ditulis, selesai.`,
      },
      outputFile: job.outputFile,
      loginHint: "agy belum login. Buka aplikasi Antigravity dan login dengan akun Google dulu.",
    };
  }
  const note = imageFiles.length ? `\n\nGambar referensi dari user ada di folder kerja: ${imageFiles.join(", ")}. Lihat sebelum menjawab.` : "";
  if (job.engine === "claude-cli") {
    return {
      bin: BIN["claude-cli"],
      args: ["-p", "--output-format", "text", "--allowedTools", "Read", ...(model ? ["--model", model] : []), ...(effort ? ["--effort", effort] : [])],
      stdin: job.instructions + note,
      loginHint: "Claude CLI belum login. Jalankan `claude` di terminal sekali dan login.",
    };
  }
  return {
    bin: BIN.codex,
    args: [
      "exec",
      "--skip-git-repo-check",
      "-o",
      "hasil.txt",
      ...imageFiles.flatMap((f) => ["--image", f]),
      ...(model ? ["-m", model] : []),
      ...(effort ? ["-c", `model_reasoning_effort=${effort}`] : []),
      "-",
    ],
    stdin: job.instructions,
    outputFile: "hasil.txt",
    loginHint: "Codex belum login. Jalankan `codex` di terminal sekali dan login.",
  };
}

async function runJob(job) {
  const done = COMPLETE[job.kind] ?? COMPLETE.markdown;
  const dir = await mkdtemp(path.join(tmpdir(), "prd-penghubung-"));
  try {
    const imageFiles = [];
    for (const [i, url] of (job.images ?? []).slice(0, 8).entries()) {
      const m = typeof url === "string" && url.match(/^data:image\/(png|jpeg|webp);base64,(.+)$/);
      if (!m) continue;
      const name = `referensi-${i + 1}.${m[1] === "jpeg" ? "jpg" : m[1]}`;
      await writeFile(path.join(dir, name), Buffer.from(m[2], "base64"));
      imageFiles.push(name);
    }
    const run = buildRun(job, imageFiles);
    for (const [n, c] of Object.entries(run.files ?? {})) await writeFile(path.join(dir, n), c, "utf8");

    const child = spawn(run.bin, run.args.map(quote), { cwd: dir, shell: isWin, windowsHide: true });
    let stdout = "";
    let stderr = "";
    let spawnError = null;
    child.stdout?.on("data", (d) => (stdout += d.toString()));
    child.stderr?.on("data", (d) => (stderr += d.toString()));
    child.on("error", (e) => (spawnError = e));
    child.stdin?.on("error", () => {});
    child.stdin?.end(run.stdin ?? "");

    const outPath = run.outputFile ? path.join(dir, run.outputFile) : "";
    const started = Date.now();
    let lastSize = -1;
    try {
      for (;;) {
        await sleep(1000);
        if (spawnError) throw new Error(`Perintah "${run.bin}" tidak bisa dijalankan di komputer ini.`);
        if (outPath) {
          const size = await stat(outPath).then((s) => s.size).catch(() => -1);
          if (size > 0 && size === lastSize) {
            const c = await readFile(outPath, "utf8");
            if (done(c)) return c;
          }
          lastSize = size;
        }
        if (child.exitCode !== null) {
          const c = outPath ? await readFile(outPath, "utf8").catch(() => "") : "";
          if (c.trim() && done(c)) return c;
          if (stdout.trim() && done(stdout)) return stdout;
          const detail = (stderr || stdout).trim().split("\n").slice(-3).join(" ").slice(0, 300);
          if (/login|log in|auth|sign in|credential|unauthori[sz]ed/i.test(detail)) throw new Error(run.loginHint);
          throw new Error(`selesai tanpa hasil yang valid.${detail ? ` Pesan: ${detail}` : ""}`);
        }
        if (Date.now() - started > TIMEOUT_MS) throw new Error(`tidak memberi hasil dalam ${Math.round(TIMEOUT_MS / 60000)} menit.`);
      }
    } finally {
      killTree(child);
    }
  } finally {
    await rm(dir, { recursive: true, force: true }).catch(() => {});
  }
}

// ---------- Komunikasi dengan web ----------
async function post(body, timeoutMs) {
  const res = await fetch(`${SERVER}/api/bridge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ code: CODE, version: VERSION, ...body }),
    signal: AbortSignal.timeout(timeoutMs),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok && res.status !== 404) throw new Error(data.error || `server menjawab ${res.status}`);
  return data;
}

/** Kirim hasil, coba ulang kalau koneksi ke web sesaat putus (hosting kadang memutus/merestart aplikasi). */
async function sendResult(body) {
  for (let i = 0; i < 8; i++) {
    try {
      await post(body, 60_000);
      return true;
    } catch {
      await sleep(Math.min(20_000, 2000 * (i + 1)));
    }
  }
  return false;
}

function validJob(j, engines) {
  return (
    j &&
    typeof j.id === "string" &&
    engines.includes(j.engine) &&
    typeof j.instructions === "string" &&
    OUTPUT_FILES.includes(j.outputFile) &&
    ["json", "markdown", "html"].includes(j.kind) &&
    (j.images === undefined || Array.isArray(j.images))
  );
}

async function main() {
  console.log("==============================================");
  console.log("  Penghubung AI - PRD Generator");
  console.log("==============================================");
  if (!/^https?:\/\//.test(DIRECT || SERVER) || !/^[a-f0-9]{32}$/.test(CODE)) {
    console.log("File ini belum berisi alamat web & kode. Download ulang lewat tombol 'Download penghubung' di web.");
    process.exit(1);
  }
  const major = Number(process.versions.node.split(".")[0]);
  if (major < 18) {
    console.log(`Node.js kamu versi ${process.versions.node}. Butuh versi 18 atau lebih baru: https://nodejs.org`);
    process.exit(1);
  }
  const engines = Object.keys(BIN).filter((k) => hasBin(BIN[k]));
  console.log(`Web    : ${DIRECT || SERVER}${DIRECT ? " (mode langsung, tanpa server)" : ""}`);
  console.log(`Versi  : penghubung ${VERSION}`);
  console.log(`Mesin  : ${engines.length ? engines.map((e) => LABEL[e]).join(", ") : "(tidak ada)"}`);
  if (!engines.length) {
    console.log("\nTidak ada agy / claude / codex yang terpasang di komputer ini.");
    console.log("Pasang & login salah satunya dulu, lalu jalankan penghubung ini lagi.");
    process.exit(1);
  }
  if (engines.includes("agy")) console.log(`Mode otomatis agy: ${AGY_AUTO ? "aktif" : "mati (AGY_AUTO_APPROVE=0)"}`);
  console.log("\nBiarkan jendela ini terbuka. Kembali ke web, lalu pilih mesinnya di menu Mesin AI.\n");
  if (DIRECT) return serveDirect(engines);

  let active = 0;
  let connected = false;
  let failures = 0;
  let warned = false;
  const seen = new Set();
  for (;;) {
    try {
      const take = active < MAX_JOBS;
      const d = await post({ action: "poll", engines, busy: active, take }, 40_000);
      if (!connected) {
        log("Tersambung ke web. Menunggu tugas...");
        connected = true;
      }
      failures = 0;
      if (d.bridgeVersion > VERSION && !warned) {
        warned = true;
        log("Ada versi penghubung yang lebih baru. Tutup jendela ini, klik 'Download penghubung' di web, lalu jalankan yang baru.");
      }
      if (d.job && validJob(d.job, engines)) {
        const job = d.job;
        // Beri tahu web bahwa tugas sudah diterima (kalau tidak, web mengirim ulang tugas ini).
        void post({ action: "ack", id: job.id }, 15_000).catch(() => {});
        if (seen.has(job.id)) continue; // tugas kiriman ulang yang sudah/sedang dikerjakan
        seen.add(job.id);
        if (seen.size > 500) seen.delete(seen.values().next().value);
        active++;
        log(`Tugas baru untuk ${LABEL[job.engine]} (${job.kind})...`);
        const t0 = Date.now();
        runJob(job)
          .then(
            async (text) => {
              const ok = await sendResult({ action: "result", id: job.id, text });
              log(ok ? `Selesai dalam ${Math.round((Date.now() - t0) / 1000)} dtk, hasil dikirim.` : "Hasil sudah jadi tapi gagal dikirim ke web (koneksi putus). Coba lagi dari web.");
            },
            async (e) => {
              const msg = String(e?.message || e);
              log(`Gagal: ${msg}`);
              await sendResult({ action: "result", id: job.id, error: msg });
            },
          )
          .finally(() => active--);
      } else if (!take) {
        await sleep(2000);
      }
    } catch (e) {
      failures++;
      if (connected || failures === 1) log(`Tidak bisa menghubungi web (${e?.message || e}). Mencoba lagi...`);
      connected = false;
      await sleep(Math.min(30_000, 2000 * failures));
    }
  }
}

// ---------- Mode langsung (web statis, mis. GitHub Pages) ----------
// Pintu hanya di 127.0.0.1 (tidak bisa diakses komputer lain). Setiap permintaan wajib:
// Host = 127.0.0.1/localhost:PORT (tahan DNS rebinding), Origin = alamat web asal file ini, dan kode rahasia.
function sameCode(given) {
  const a = Buffer.from(String(given || ""));
  const b = Buffer.from(CODE);
  return a.length === b.length && timingSafeEqual(a, b);
}

function serveDirect(engines) {
  let active = 0;
  const waiters = [];
  const acquire = () => (active < MAX_JOBS ? (active++, Promise.resolve()) : new Promise((r) => waiters.push(r)));
  const release = () => {
    const next = waiters.shift();
    if (next) next();
    else active--;
  };
  const hostOk = (h) => h === `127.0.0.1:${PORT}` || h === `localhost:${PORT}`;
  const server = createServer(async (req, res) => {
    const origin = req.headers.origin || "";
    const send = (status, data) => {
      res.writeHead(status, { "Content-Type": "application/json", "Access-Control-Allow-Origin": DIRECT, Vary: "Origin", "Cache-Control": "no-store" });
      res.end(JSON.stringify(data));
    };
    if (!hostOk(req.headers.host) || origin !== DIRECT) {
      res.writeHead(403).end();
      return;
    }
    if (req.method === "OPTIONS") {
      res.writeHead(204, {
        "Access-Control-Allow-Origin": DIRECT,
        "Access-Control-Allow-Methods": "GET, POST",
        "Access-Control-Allow-Headers": "content-type, x-prd-code",
        "Access-Control-Allow-Private-Network": "true",
        "Access-Control-Max-Age": "600",
        Vary: "Origin",
      });
      res.end();
      return;
    }
    if (!sameCode(req.headers["x-prd-code"])) return send(401, { error: "Kode penghubung tidak cocok. Download ulang penghubung dari web ini." });
    const url = new URL(req.url || "/", `http://127.0.0.1:${PORT}`);
    if (req.method === "GET" && url.pathname === "/status") return send(200, { alive: true, version: VERSION, engines, busy: active });
    if (req.method === "POST" && url.pathname === "/run") {
      let raw = "";
      let size = 0;
      for await (const chunk of req) {
        size += chunk.length;
        if (size > 40 * 1024 * 1024) return send(413, { error: "Permintaan terlalu besar." });
        raw += chunk;
      }
      let job;
      try {
        job = { id: "direct", ...JSON.parse(raw) };
      } catch {
        return send(400, { error: "Permintaan tidak valid." });
      }
      if (!validJob(job, engines)) return send(400, { error: "Mesin tidak tersedia di penghubung ini, atau permintaan tidak valid." });
      await acquire();
      const t0 = Date.now();
      log(`Tugas baru untuk ${LABEL[job.engine]} (${job.kind})...`);
      try {
        const text = await runJob(job);
        log(`Selesai dalam ${Math.round((Date.now() - t0) / 1000)} dtk, hasil dikirim.`);
        return send(200, { text });
      } catch (e) {
        const msg = String(e?.message || e);
        log(`Gagal: ${msg}`);
        return send(500, { error: msg });
      } finally {
        release();
      }
    }
    return send(404, { error: "Tidak ada." });
  });
  server.requestTimeout = 0; // tugas AI bisa beberapa menit
  server.on("error", (e) => {
    if (e.code === "EADDRINUSE") console.log(`Port ${PORT} sudah dipakai. Mungkin penghubung lain masih terbuka: tutup jendelanya dulu, lalu jalankan lagi.`);
    else console.log(`Penghubung tidak bisa dibuka: ${e.message}`);
    process.exit(1);
  });
  server.listen(PORT, "127.0.0.1", () => log(`Siap di http://127.0.0.1:${PORT} untuk ${DIRECT}. Menunggu tugas...`));
}

main();
